
fetch("graph.json").then(r => r.json()).then(data => {
  const svg = d3.select("#graph");
  const w = 800, h = 600;

  const sim = d3.forceSimulation(data.nodes)
    .force("link", d3.forceLink(data.links).id(d => d.id).distance(100))
    .force("charge", d3.forceManyBody().strength(-200))
    .force("center", d3.forceCenter(w / 2, h / 2));

  const link = svg.selectAll("line").data(data.links).join("line")
    .attr("stroke", "#666");

  const node = svg.selectAll("g").data(data.nodes).join("g")
    .style("cursor", "pointer")
    .on("click", (e, d) => window.location = d.url)
    .call(d3.drag()
      .on("start", (e, d) => { if (!e.active) sim.alphaTarget(0.3).restart(); d.fx = d.x; d.fy = d.y; })
      .on("drag",  (e, d) => { d.fx = e.x; d.fy = e.y; })
      .on("end",   (e, d) => { if (!e.active) sim.alphaTarget(0); d.fx = null; d.fy = null; }));

  node.append("circle").attr("r", 6).attr("fill", "#aaa");
  node.append("text").text(d => d.id).attr("dy", 20)
    .attr("text-anchor", "middle").attr("fill", "#ddd").attr("font-size", 12);

  sim.on("tick", () => {
    link.attr("x1", d => d.source.x).attr("y1", d => d.source.y)
        .attr("x2", d => d.target.x).attr("y2", d => d.target.y);
    node.attr("transform", d => `translate(${d.x},${d.y})`);
  });
});
